  `funding_type` enum('budget','paid') COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'budget',
  `is_benefit` tinyint(1) NOT NULL DEFAULT '0',
  `benefit_type` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `needs_dorm` tinyint(1) NOT NULL DEFAULT '0',
  `is_first_spo` tinyint(1) NOT NULL DEFAULT '1',
  `signed_doc_photo` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `rejection_reason` text COLLATE utf8mb4_unicode_ci,
  `app_last_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_first_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_middle_name` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_birth_date` date DEFAULT NULL,
  `app_passport_series` varchar(4) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_passport_number` varchar(6) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_passport_issued_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_snils` varchar(14) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_prev_education` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_edu_doc_series` varchar(10) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_edu_doc_number` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_edu_doc_issued_by` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_edu_issue_date` date DEFAULT NULL,
  `app_avg_cert_score` decimal(3,2) DEFAULT NULL,
  `app_phone` varchar(20) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_photo_passport` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_photo_snils` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_photo_edu_1` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_photo_edu_2` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `app_photo_edu_3` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  `cancelled_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `applications_applicant_id_foreign` (`applicant_id`),
  KEY `applications_program_id_foreign` (`program_id`),
  CONSTRAINT `applications_applicant_id_foreign` FOREIGN KEY (`applicant_id`) REFERENCES `applicants` (`id`) ON DELETE RESTRICT,
  CONSTRAINT `applications_program_id_foreign` FOREIGN KEY (`program_id`) REFERENCES `programs` (`id`) ON DELETE RESTRICT
) ENGINE=InnoDB AUTO_INCREMENT=73 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
